CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz DEFAULT now());
DO $$ BEGIN CREATE ROLE atlas_app NOLOGIN; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE OR REPLACE FUNCTION atlas_actor() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT NULLIF(current_setting('atlas.actor', true),'')::uuid $$;
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text UNIQUE NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE resources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users, type text NOT NULL CHECK(type IN ('color','palette','website')), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200), aliases text[] NOT NULL DEFAULT '{}', description text NOT NULL DEFAULT '', source_url text NOT NULL DEFAULT '', source_kind text NOT NULL DEFAULT 'manual', source_metadata jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')), visibility text NOT NULL DEFAULT 'private' CHECK(visibility IN ('private','public')), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, deleted_at timestamptz);
CREATE INDEX resources_owner_recent ON resources(owner_id,updated_at DESC,id) WHERE deleted_at IS NULL;
CREATE INDEX resources_public ON resources(type,published_at DESC,id) WHERE status='published' AND visibility='public' AND deleted_at IS NULL;
CREATE TABLE resource_colors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), resource_id uuid NOT NULL REFERENCES resources ON DELETE CASCADE, position integer NOT NULL CHECK(position>=0), role text NOT NULL DEFAULT '', label text NOT NULL DEFAULT '', value jsonb NOT NULL CHECK(jsonb_typeof(value)='object' AND (value->>'alpha')::numeric BETWEEN 0 AND 1 AND value->>'schemaVersion'='1'), match_key text NOT NULL, UNIQUE(resource_id,position));
CREATE INDEX resource_color_match ON resource_colors(match_key,resource_id);
CREATE TABLE website_details (resource_id uuid PRIMARY KEY REFERENCES resources ON DELETE CASCADE, original_url text NOT NULL, normalized_url text NOT NULL CHECK(normalized_url ~ '^https?://'));
CREATE INDEX website_url ON website_details(normalized_url);
CREATE TABLE resource_private_notes (resource_id uuid PRIMARY KEY REFERENCES resources ON DELETE CASCADE, owner_id uuid NOT NULL REFERENCES users, body text NOT NULL DEFAULT '', rating integer CHECK(rating BETWEEN 1 AND 5));
CREATE TABLE user_resource_state (user_id uuid NOT NULL REFERENCES users, resource_id uuid NOT NULL REFERENCES resources ON DELETE CASCADE, is_favorite boolean NOT NULL DEFAULT false, PRIMARY KEY(user_id,resource_id));
CREATE TABLE categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users, parent_id uuid REFERENCES categories ON DELETE SET NULL, name text NOT NULL, slug text NOT NULL, UNIQUE(owner_id,slug));
CREATE TABLE resource_categories (resource_id uuid NOT NULL REFERENCES resources ON DELETE CASCADE, category_id uuid NOT NULL REFERENCES categories ON DELETE CASCADE, is_primary boolean NOT NULL DEFAULT false, PRIMARY KEY(resource_id,category_id));
CREATE UNIQUE INDEX one_primary_category ON resource_categories(resource_id) WHERE is_primary;
CREATE INDEX category_resources ON resource_categories(category_id,resource_id);
CREATE TABLE tags (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users, name text NOT NULL, normalized_name text NOT NULL, UNIQUE(owner_id,normalized_name));
CREATE TABLE resource_tags (resource_id uuid NOT NULL REFERENCES resources ON DELETE CASCADE, tag_id uuid NOT NULL REFERENCES tags ON DELETE CASCADE, PRIMARY KEY(resource_id,tag_id));
CREATE INDEX tag_resources ON resource_tags(tag_id,resource_id);
CREATE TABLE collections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users, name text NOT NULL, description text NOT NULL DEFAULT '', visibility text NOT NULL DEFAULT 'private' CHECK(visibility IN ('private','public')));
CREATE TABLE collection_items (collection_id uuid NOT NULL REFERENCES collections ON DELETE CASCADE, resource_id uuid NOT NULL REFERENCES resources ON DELETE CASCADE, position integer NOT NULL, PRIMARY KEY(collection_id,resource_id), UNIQUE(collection_id,position) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE import_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users, source_hash text NOT NULL, result jsonb NOT NULL, UNIQUE(owner_id,source_hash));
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL REFERENCES users, resource_id uuid, action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE resources ENABLE ROW LEVEL SECURITY;
CREATE POLICY resource_read ON resources FOR SELECT USING(owner_id=atlas_actor() OR (status='published' AND visibility='public' AND deleted_at IS NULL));
CREATE POLICY resource_write ON resources FOR ALL USING(owner_id=atlas_actor()) WITH CHECK(owner_id=atlas_actor());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['resource_colors','website_details'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY child_read ON %I FOR SELECT USING(EXISTS(SELECT 1 FROM resources r WHERE r.id=resource_id))',t);
 EXECUTE format('CREATE POLICY child_write ON %I FOR ALL USING(EXISTS(SELECT 1 FROM resources r WHERE r.id=resource_id AND r.owner_id=atlas_actor())) WITH CHECK(EXISTS(SELECT 1 FROM resources r WHERE r.id=resource_id AND r.owner_id=atlas_actor()))',t);
END LOOP; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['categories','tags','collections','import_jobs','resource_private_notes'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY owned ON %I FOR ALL USING(owner_id=atlas_actor()) WITH CHECK(owner_id=atlas_actor())',t);
END LOOP; END $$;
CREATE POLICY collection_public ON collections FOR SELECT USING(visibility='public');
CREATE OR REPLACE FUNCTION atlas_public_category(cid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM resource_categories rc JOIN resources r ON r.id=rc.resource_id WHERE rc.category_id=cid AND r.status='published' AND r.visibility='public' AND r.deleted_at IS NULL) $$;
CREATE POLICY category_public ON categories FOR SELECT USING(atlas_public_category(id));
CREATE OR REPLACE FUNCTION atlas_public_tag(tid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM resource_tags rt JOIN resources r ON r.id=rt.resource_id WHERE rt.tag_id=tid AND r.status='published' AND r.visibility='public' AND r.deleted_at IS NULL) $$;
CREATE POLICY tag_public ON tags FOR SELECT USING(atlas_public_tag(id));
ALTER TABLE resource_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY rc_read ON resource_categories FOR SELECT USING(EXISTS(SELECT 1 FROM resources r WHERE r.id=resource_id));
CREATE POLICY rc_write ON resource_categories FOR ALL USING(EXISTS(SELECT 1 FROM resources r WHERE r.id=resource_id AND r.owner_id=atlas_actor())) WITH CHECK(EXISTS(SELECT 1 FROM resources r WHERE r.id=resource_id AND r.owner_id=atlas_actor()) AND EXISTS(SELECT 1 FROM categories c WHERE c.id=category_id AND c.owner_id=atlas_actor()));
ALTER TABLE resource_tags ENABLE ROW LEVEL SECURITY;
CREATE POLICY rt_read ON resource_tags FOR SELECT USING(EXISTS(SELECT 1 FROM resources r WHERE r.id=resource_id));
CREATE POLICY rt_write ON resource_tags FOR ALL USING(EXISTS(SELECT 1 FROM resources r WHERE r.id=resource_id AND r.owner_id=atlas_actor())) WITH CHECK(EXISTS(SELECT 1 FROM resources r WHERE r.id=resource_id AND r.owner_id=atlas_actor()) AND EXISTS(SELECT 1 FROM tags t WHERE t.id=tag_id AND t.owner_id=atlas_actor()));
ALTER TABLE collection_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY ci_read ON collection_items FOR SELECT USING(EXISTS(SELECT 1 FROM collections c WHERE c.id=collection_id) AND EXISTS(SELECT 1 FROM resources r WHERE r.id=resource_id));
CREATE POLICY ci_write ON collection_items FOR ALL USING(EXISTS(SELECT 1 FROM collections c WHERE c.id=collection_id AND c.owner_id=atlas_actor())) WITH CHECK(EXISTS(SELECT 1 FROM collections c WHERE c.id=collection_id AND c.owner_id=atlas_actor()) AND EXISTS(SELECT 1 FROM resources r WHERE r.id=resource_id AND r.owner_id=atlas_actor()));
ALTER TABLE user_resource_state ENABLE ROW LEVEL SECURITY;
CREATE POLICY state_owned ON user_resource_state FOR ALL USING(user_id=atlas_actor()) WITH CHECK(user_id=atlas_actor() AND EXISTS(SELECT 1 FROM resources WHERE id=resource_id AND owner_id=atlas_actor()));
ALTER TABLE audit_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_owned ON audit_events FOR ALL USING(actor_id=atlas_actor()) WITH CHECK(actor_id=atlas_actor());
CREATE OR REPLACE FUNCTION check_color_count() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE rid uuid; kind text; n integer; BEGIN
 IF TG_TABLE_NAME='resources' THEN rid=COALESCE(NEW.id,OLD.id); ELSE rid=COALESCE(NEW.resource_id,OLD.resource_id); END IF;
 SELECT type INTO kind FROM resources WHERE id=rid;
 IF kind IS NULL THEN RETURN NULL; END IF;
 SELECT count(*) INTO n FROM resource_colors WHERE resource_id=rid;
 IF (kind='color' AND n<>1) OR (kind='palette' AND (n<2 OR n>24)) OR (kind='website' AND n<>0) THEN RAISE EXCEPTION 'Invalid color count'; END IF;
 RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER resource_color_count AFTER INSERT OR UPDATE ON resources DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_color_count();
CREATE CONSTRAINT TRIGGER child_color_count AFTER INSERT OR UPDATE OR DELETE ON resource_colors DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_color_count();
GRANT USAGE ON SCHEMA public TO atlas_app;
GRANT SELECT,INSERT,UPDATE,DELETE ON resources,resource_colors,website_details,resource_private_notes,user_resource_state,categories,resource_categories,tags,resource_tags,collections,collection_items,import_jobs,audit_events TO atlas_app;
INSERT INTO schema_migrations(version) VALUES('001');
